#include <algorithm>
#include <cstdint>
#include <iomanip>
#include <iostream>

// A model of this Mac's steady_clock, in picoseconds: it counts in nanoseconds, but its
// counter moves once every 41.667 ns, and a call to now() takes about 12 ns.
const int64_t kTick = 41'667;      // between two steps of the counter
const int64_t kReadCost = 12'000;  // one call to now()
const int64_t kLoad = 900;         // one load that hits L1, 0.9 ns

// What now() returns when the counter is read at true time t.
int64_t read_clock(int64_t t) {
    return t / kTick * kTick;
}

// What two reads around n loads measure, when the first read happens at true time t0.
int64_t measure(int64_t t0, long n) {
    const int64_t start = read_clock(t0);
    const int64_t end = read_clock(t0 + kReadCost + n * kLoad);  // after the call returns and n loads run
    return end - start;
}

int main() {
    int64_t shortest = measure(0, 1), longest = shortest, total = 0;
    for (int64_t k = 0; k < 1000; ++k) {  // one load, timed from 1000 start times across one tick
        const int64_t m = measure(k * kTick / 1000, 1);
        shortest = std::min(shortest, m);
        longest = std::max(longest, m);
        total += m;
    }
    std::cout << std::fixed << std::setprecision(3);
    std::cout << "one load, timed 1000 times: shortest " << shortest / 1000.0 << " ns, longest " << longest / 1000.0
              << " ns, average " << total / 1000 / 1000.0 << " ns\n";
    for (long n : {1L, 64L, 1000L, 1000000L}) {
        std::cout << "timing " << n << " at once: " << measure(17'000, n) / 1000.0 / n << " ns a load\n";
    }
    return 0;
}

