// -O2
#include <chrono>
#include <cstdint>
#include <cstdlib>
#include <iostream>
#include <random>
#include <utility>
#include <vector>

using std::chrono::steady_clock;

// A random cycle through n slots: shuffle the order to visit them in, then link each slot to the next.
std::vector<uint32_t> random_cycle(std::size_t n, uint32_t seed) {
    std::vector<uint32_t> order(n);
    for (std::size_t i = 0; i < n; ++i) order[i] = static_cast<uint32_t>(i);
    std::mt19937 rng(seed);
    for (std::size_t i = n - 1; i > 0; --i) {
        std::swap(order[i], order[rng() % (i + 1)]);  // any of slots 0 to i
    }
    std::vector<uint32_t> next(n);
    for (std::size_t k = 0; k + 1 < n; ++k) next[order[k]] = order[k + 1];
    next[order[n - 1]] = order[0];  // and the last one back to the first
    return next;
}

int main(int argc, char* argv[]) {
    const std::size_t n = argc > 1 ? std::atol(argv[1]) : 1 << 20;  // 2^20 slots of 4 bytes: 4 MB
    const std::vector<uint32_t> next = random_cycle(n, 42);

    auto t0 = steady_clock::now();
    uint64_t sum = 0;  // throughput: every address is known before any load finishes
    for (std::size_t k = 0; k < n; ++k) sum += next[k];
    auto t1 = steady_clock::now();
    // std::cout << "sum:   " << std::chrono::duration<double, std::nano>(t1 - t0).count() / n << " ns a load\n";

    t0 = steady_clock::now();
    uint64_t chased = 0;  // latency: each address is the result of the load before
    uint32_t i = 0;
    for (std::size_t k = 0; k < n; ++k) {
        i = next[i];
        chased += i;
    }
    t1 = steady_clock::now();
    // std::cout << "chase: " << std::chrono::duration<double, std::nano>(t1 - t0).count() / n << " ns a load\n";

    std::cout << "slots:  " << n << '\n';
    std::cout << "sum:    " << sum << '\n';
    std::cout << "chased: " << chased << '\n';
    std::cout << "back at slot 0: " << std::boolalpha << (i == 0) << '\n';
    return 0;
}

