#include <algorithm>
#include <chrono>
#include <cstdint>
#include <cstdlib>
#include <iostream>
#include <random>
#include <utility>
#include <vector>

// A random cycle through n slots: shuffle the order to visit them in, then link each slot to the next.
std::vector<uint32_t> random_cycle(std::size_t n, uint32_t seed) {
    std::vector<uint32_t> order(n);
    for (std::size_t i = 0; i < n; ++i) order[i] = static_cast<uint32_t>(i);
    std::mt19937 rng(seed);
    for (std::size_t i = n - 1; i > 0; --i) {
        std::swap(order[i], order[rng() % (i + 1)]);  // any of slots 0 to i
    }
    std::vector<uint32_t> next(n);
    for (std::size_t k = 0; k + 1 < n; ++k) next[order[k]] = order[k + 1];
    next[order[n - 1]] = order[0];  // and the last one back to the first
    return next;
}

// True when following next from slot 0 visits every slot once and comes back to 0.
bool one_cycle(const std::vector<uint32_t>& next) {
    std::vector<bool> seen(next.size(), false);
    uint32_t i = 0;
    for (std::size_t k = 0; k < next.size(); ++k) {
        if (seen[i]) return false;  // back at a slot too early: a smaller loop
        seen[i] = true;
        i = next[i];
    }
    return i == 0;
}

// The median time of one load over `reps` runs of `steps` loads, after a warm-up.
double chase_ns(const std::vector<uint32_t>& next, long steps, int reps, uint64_t& keep) {
    uint32_t i = 0;
    const long warm = std::max(steps, static_cast<long>(next.size()));
    for (long s = 0; s < warm; ++s) i = next[i];  // warm up the caches, the TLB, and the core
    std::vector<double> ns;
    for (int r = 0; r < reps; ++r) {
        const auto t0 = std::chrono::steady_clock::now();
        for (long s = 0; s < steps; ++s) i = next[i];
        const auto t1 = std::chrono::steady_clock::now();
        keep += i;  // the chain's result is used, so -O2 can't delete it
        ns.push_back(std::chrono::duration<double, std::nano>(t1 - t0).count() / steps);
    }
    std::sort(ns.begin(), ns.end());
    return ns[ns.size() / 2];
}

int main(int argc, char* argv[]) {
    const std::size_t kb = argc > 1 ? std::atol(argv[1]) : 256;  // ./honest 65536 on your machine
    const std::vector<uint32_t> next = random_cycle(kb * 1024 / sizeof(uint32_t), 42);
    std::cout << kb << " KB, " << next.size() << " slots, one cycle: " << std::boolalpha << one_cycle(next) << '\n';

    uint64_t keep = 0;
    const double ns = chase_ns(next, 10'000'000, 7, keep);
    std::cout << "7 runs of 10000000 loads, kept " << keep << '\n';
    // std::cout << "median " << ns << " ns a load\n";
    return 0;
}

