std::size_t loop_length(const std::vector<uint32_t>& next) {
    std::size_t length = 0;
    uint32_t i = 0;
    do {
        i = next[i];
        ++length;
    } while (i != 0 && length < next.size());
    return length;
}

int main() {
    std::size_t n = 0;
    uint32_t seed = 0;
    std::cin >> n >> seed;
    const std::vector<uint32_t> order = shuffled(n, seed);
    const std::size_t plain = loop_length(order);  // the shuffle itself used as next
    const std::size_t linked = loop_length(link(order));
    std::cout << "plain shuffle: slot 0's loop has " << plain << " of " << n << " slots\n";
    std::cout << "linked order:  slot 0's loop has " << linked << " of " << n << " slots\n";
    std::cout << "every slot once: " << std::boolalpha << (linked == n) << '\n';
    return 0;
}
